/** Exact declined variants retain their identities and reasons before an executable exists. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbNativeVariantDeclineIdentityTest {
	private final Map<String, String> previous = new LinkedHashMap<>();

	@BeforeEach
	void configure() {
		set("rdf4j.lmdb.packedFtree.enabled", "true");
		set("rdf4j.lmdb.packedFtree.parallel.enabled", "true");
		set("rdf4j.lmdb.parallel.enabled", "true");
		set("rdf4j.lmdb.parallel.threads", "4");
		set("rdf4j.lmdb.parallel.maxTasks", "4");
		set("rdf4j.lmdb.packedFtree.parallel.minRootsPerPartition", "128");
		set(LmdbNativePackedMorsels.ROWS_PROPERTY, "128");
	}

	@AfterEach
	void restore() {
		previous.forEach((name, value) -> {
			if (value == null) {
				System.clearProperty(name);
			} else {
				System.setProperty(name, value);
			}
		});
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void captureKeepsSeparateVariantsInRuntimeAndPreview(boolean preview) {
		Map<String, String> captured = new LinkedHashMap<>();
		Map<String, String> old = LmdbNativeAttemptMetrics.installDeclineCapture(captured);
		try (QueryExplanationContext ignored = preview
				? QueryExplanationContext.enter(Explanation.Level.Optimized)
				: null) {
			LmdbNativeAttemptMetrics.recordDecline(null, LmdbNativePackedFtree.ROWS_SERIAL, "serial-refusal");
			LmdbNativeAttemptMetrics.recordDecline(null, LmdbNativePackedFtree.ROWS_PARALLEL, "task-budget");
			assertThat(captured).containsExactly(
					Map.entry(LmdbNativePackedFtree.ROWS_SERIAL, "serial-refusal"),
					Map.entry(LmdbNativePackedFtree.ROWS_PARALLEL, "task-budget"));
		} finally {
			LmdbNativeAttemptMetrics.installDeclineCapture(old);
		}
	}

	@Test
	void diagnosticCaptureKeepsSeparateVariants() {
		Map<String, String> captured = new LinkedHashMap<>();
		Map<String, String> old = LmdbNativeAttemptMetrics.installDeclineCapture(captured);
		try {
			LmdbNativeAttemptMetrics.captureDecline(LmdbNativePackedFtree.ROWS_SERIAL, "serial-refusal");
			LmdbNativeAttemptMetrics.captureDecline(LmdbNativePackedFtree.ROWS_PARALLEL, "task-budget");
			assertThat(captured).containsExactly(
					Map.entry(LmdbNativePackedFtree.ROWS_SERIAL, "serial-refusal"),
					Map.entry(LmdbNativePackedFtree.ROWS_PARALLEL, "task-budget"));
		} finally {
			LmdbNativeAttemptMetrics.installDeclineCapture(old);
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void bothDisabledVariantsRemainVisible(boolean named) throws Exception {
		set("rdf4j.lmdb.packedFtree.enabled", "false");
		LmdbNativeDecisionRecord record = packedPreview(named, false);
		assertDeclinedPair(record, "disabled", "parallel-ineligible");
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void parallelSerialPlanningRefusalIsRoutedToItsOwnVariant(boolean named) throws Exception {
		LmdbNativeDecisionRecord record = packedPreview(named, true);
		assertDeclinedPair(record, "unsupported-shape", "unsupported-shape");
	}

	@Test
	void namedBudgetRefusalKeepsTheSpecificReason() throws Exception {
		try (var holder = LmdbNativeParallelPipelines.tryReserveTasks(false, 4)) {
			assertThat(holder).isNotNull();
			assertThat(holder.grantedWorkers()).isEqualTo(4);
			LmdbNativeDecisionRecord record = packedPreview(true, false);
			assertThat(record.entries()).filteredOn(entry -> !entry.admitted())
					.containsExactly(LmdbNativeDecisionRecord.Entry.declined(
							LmdbNativePackedFtree.ROWS_PARALLEL, "task-budget"));
		}
		try (var restored = LmdbNativeParallelPipelines.tryReserveTasks(false, 4)) {
			assertThat(restored).isNotNull();
			assertThat(restored.grantedWorkers()).isEqualTo(4);
		}
	}

	@Test
	void genuinelyAnonymousOfferKeepsItsOrdinalFallback() throws Exception {
		LmdbNativeOfferBridge<String> offers = new LmdbNativeOfferBridge<>(LmdbNativeDecisionPoint.ROW);
		offers.offer(() -> null);
		LmdbNativeDecisionRecord record = preview(offers);
		assertThat(record.entries()).extracting(LmdbNativeDecisionRecord.Entry::id).containsExactly("offer#1");
		assertThat(record.entries().getFirst().declineReason()).isNotBlank();
	}

	@ParameterizedTest
	@ValueSource(strings = { "packedFtree", "packedFtree(parallel)" })
	void forcingStillFindsTheCorrespondingExactRefusal(String forced) {
		LmdbNativeOfferBridge<String> offers = new LmdbNativeOfferBridge<>(LmdbNativeDecisionPoint.ROW);
		offers.offer(() -> {
			LmdbNativeAttemptMetrics.recordDecline(null, LmdbNativePackedFtree.ROWS_SERIAL, "serial-refusal");
			return null;
		});
		offers.offer(() -> {
			LmdbNativeAttemptMetrics.recordDecline(null, LmdbNativePackedFtree.ROWS_PARALLEL, "task-budget");
			return null;
		});
		Throwable failure = catchThrowable(() -> new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW,
				offers.strategies(), null).forcing(forced).dispatch(null));
		assertThat(failure).isInstanceOf(QueryEvaluationException.class)
				.hasMessageContaining(forced.equals("packedFtree") ? "serial-refusal" : "task-budget");
		assertThat(LmdbNativeForceableStrategies.matches("packedFtree", LmdbNativePackedFtree.ROWS_SERIAL)).isTrue();
		assertThat(LmdbNativeForceableStrategies.matches("packedFtree", LmdbNativePackedFtree.ROWS_PARALLEL)).isTrue();
		assertThat(LmdbNativeForceableStrategies.matches(LmdbNativePackedFtree.ROWS_SERIAL,
				LmdbNativePackedFtree.ROWS_PARALLEL)).isFalse();
		assertThat(LmdbNativeForceableStrategies.isForceable("offer#1")).isFalse();
	}

	private static void assertDeclinedPair(LmdbNativeDecisionRecord record, String serial, String parallel) {
		assertThat(record.entries()).containsExactly(
				LmdbNativeDecisionRecord.Entry.declined(LmdbNativePackedFtree.ROWS_SERIAL, serial),
				LmdbNativeDecisionRecord.Entry.declined(LmdbNativePackedFtree.ROWS_PARALLEL, parallel));
	}

	private static LmdbNativeDecisionRecord packedPreview(boolean named, boolean bound) throws Exception {
		NativeLmdbQuerySource source = new StatsSource(10_000L).predicate(1L, 1D, 500L)
				.predicate(2L, 1D, 500L)
				.adjacencyServed(true);
		RowState row = row(source);
		MultiJoinPlan input = new MultiJoinPlan(new SlotPlan[] { edge(0, 1L, 1, 500D), edge(0, 2L, 2, 500D) },
				new MaskedFilter[0]);
		if (bound) {
			row.slots[0] = 123L;
			row.recomputeBoundMask();
			assertThat(LmdbNativePackedMorsels.eligible(input, row)).isTrue();
			assertThat(LmdbNativePackedFtree.Planner.plan(input, row, new int[] { 0, 1, 2 })).isNull();
		}
		try {
			LmdbNativeOfferBridge<NativeUnorderedInput> offers = new LmdbNativeOfferBridge<>(
					LmdbNativeDecisionPoint.ROW);
			offers.offer(named ? LmdbNativePackedFtree.ROWS_SERIAL : null,
					() -> LmdbNativePackedFtree.proposeRows((SlotPlan) input, row, new int[] { 0, 1, 2 }, false,
							null));
			offers.offer(named ? LmdbNativePackedFtree.ROWS_PARALLEL : null,
					() -> LmdbNativePackedFtree.proposeParallelRows(input, row, new int[] { 0, 1, 2 }, false,
							null));
			return preview(offers);
		} finally {
			row.memoryScope.close();
		}
	}

	private static <T> LmdbNativeDecisionRecord preview(LmdbNativeOfferBridge<T> offers) throws Exception {
		try (QueryExplanationContext ignored = QueryExplanationContext.enter(Explanation.Level.Optimized)) {
			return new LmdbNativeDispatchLoop<>(LmdbNativeDecisionPoint.ROW, offers.strategies(), null).preview(null);
		}
	}

	private void set(String name, String value) {
		if (!previous.containsKey(name)) {
			previous.put(name, System.getProperty(name));
		}
		System.setProperty(name, value);
	}
}
